function openTranslationView(message){if(!Navigator||!Navigation){(async function(){const text=extractMessageText(message);if(!text){showToast("No text to translate");return}showToast("Translating…");const result=await translateEnglishToFrench(text);showToast(result.ok?(result.text.slice(0,120)+(result.text.length>120?"…":"")):result.error.slice(0,140))})();return}const screen=function(){return React.createElement(Navigator,{initialRouteName:"TranslationCordResult",goBackOnBackPress:true,screens:{TranslationCordResult:{title:"Translation",headerLeft:modalCloseButton?modalCloseButton(function(){Navigation.pop()}):undefined,render:function(){return React.createElement(TranslationResultScreen,{message:message})}}}})};try{ActionSheet&&ActionSheet.hideActionSheet&&ActionSheet.hideActionSheet()}catch(e){}Navigation.push(screen)}
function injectMenuItem(buttons,message){if(!Array.isArray(buttons))return;if(buttons.some(function(b){return(b&&b.props&&b.props.label===MENU_LABEL)||(b&&b.key===MENU_ID)}))return;const iconSource=getAssetIDByName("ic_language")||getAssetIDByName("LanguageIcon")||getAssetIDByName("ChatIcon");const onPress=function(){openTranslationView(message)};if(ActionSheetRow){buttons.push(React.createElement(ActionSheetRow,{key:MENU_ID,label:MENU_LABEL,icon:iconSource?React.createElement(ActionSheetRow.Icon,{source:iconSource}):undefined,onPress:onPress}))}else{const ButtonRow=(findByProps("ButtonRow")||{}).ButtonRow;if(ButtonRow)buttons.push(React.createElement(ButtonRow,{key:MENU_ID,label:MENU_LABEL,onPress:onPress}))}}
